{
  "IP": "neorv32_trng",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Generated random bytes",
      "Unit": "neorv32_trng",
      "Information": "Unpredictable bytes generated by the entropy cells, debiased, accumulated and buffered for software reads; the TRNG depends on providing these bytes.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "yes"
      },
      "Rubric Reason": "Confidentiality: generated bytes are exposed in the software read response through fifo.rdata at line 117. Integrity: the enable and FIFO-clear path can discard pending generated values and cause a zero replacement on the read path at lines 115-117 and 170. Availability: disabling generation or clearing the FIFO can withhold the bytes, as shown at lines 137, 170 and 114-117. Undermined Expected Behavior: the SIM_MODE build choice selects simulated rather than physical inverter behavior at lines 132 and 439-451, and the RTL warns that simulation mode provides no true physical random output at lines 288-289.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could read the response to obtain generated bytes, disable or clear the generator and FIFO to discard them, or integrate the IP in simulation mode so its output is not true physical randomness.",
      "Enters Through": [],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        360,
        366
      ],
      "Exit Lines": [
        117
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "TRNG enable setting",
      "Unit": "neorv32_trng",
      "Information": "The software-programmable enable setting controls whether entropy sampling runs and whether the random-data FIFO is cleared; TRNG operation depends on this setting.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: a bus write changes the stored enable setting at line 105. Availability: the setting controls the generator through line 137 and causes the FIFO to clear when disabled through line 170.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could write the control register with enable cleared, disabling entropy generation and clearing pending random data.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        105
      ],
      "Held Lines": [
        105
      ],
      "Exit Lines": [
        109
      ]
    }
  ],
  "Not Kept": [
